cat > tests/avatar_image_test.sh <<'EOF'
#!/bin/bash
# Production image (docs/deploy.md) must be able to upload an avatar (CLN-402).
bash scripts/build-image.sh >/dev/null || { echo "build failed"; exit 1; }
out=$(APP_ROOT=build/image bash build/image/bin/app avatar me.png)
[ "$out" = "status=201 avatar=me-256.png" ] || { echo "avatar in prod image: $out"; exit 1; }
EOF
bash tests/avatar_image_test.sh; echo exit=$?
